export const EMBEDDED_TENANT_MIGRATIONS: Record<string, string> = {
  "008_tenant_clients.sql": "-- Migration: 008_tenant_clients\n-- Tabela de clientes no schema do tenant\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\n-- NOTA: Clients no schema do tenant NÃO têm company_id (isolados por schema)\n\nCREATE TABLE IF NOT EXISTS clients (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  name VARCHAR(255) NOT NULL,\n  cnpj VARCHAR(18) NOT NULL,\n  email VARCHAR(255),\n  status VARCHAR(50) NOT NULL DEFAULT 'active',\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW(),\n  \n  -- CNPJ único por schema (não precisa company_id, já isolado por schema)\n  UNIQUE(cnpj)\n);\n\n-- Índices\nCREATE INDEX IF NOT EXISTS idx_clients_cnpj ON clients(cnpj);\nCREATE INDEX IF NOT EXISTS idx_clients_status ON clients(status);\nCREATE INDEX IF NOT EXISTS idx_clients_name ON clients(name);\n\n-- Trigger para updated_at\nCREATE TRIGGER update_clients_updated_at \n  BEFORE UPDATE ON clients \n  FOR EACH ROW \n  EXECUTE FUNCTION update_updated_at_column();\n\n-- Comentários para documentação\nCOMMENT ON TABLE clients IS 'Clientes da contabilidade (empresas atendidas) - isolados por schema';\nCOMMENT ON COLUMN clients.cnpj IS 'CNPJ único por contabilidade (isolamento por schema)';\n",
  "009_client_tax_regime.sql": "-- Migration: 009_client_tax_regime\n-- Adiciona campos de regime tributário à tabela clients\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\n\n-- Adicionar campos ao clients\nALTER TABLE clients\n  ADD COLUMN IF NOT EXISTS tax_regime VARCHAR(50),\n  ADD COLUMN IF NOT EXISTS cnae VARCHAR(10),\n  ADD COLUMN IF NOT EXISTS state_registration VARCHAR(50),\n  ADD COLUMN IF NOT EXISTS municipal_registration VARCHAR(50),\n  ADD COLUMN IF NOT EXISTS notes TEXT;\n\n-- Criar índice para tax_regime (útil para filtros)\nCREATE INDEX IF NOT EXISTS idx_clients_tax_regime ON clients(tax_regime);\n\n-- Comentários para documentação\nCOMMENT ON COLUMN clients.tax_regime IS 'Regime tributário: simples_nacional, lucro_presumido, lucro_real, outros';\nCOMMENT ON COLUMN clients.cnae IS 'Código CNAE principal da empresa';\nCOMMENT ON COLUMN clients.state_registration IS 'Inscrição Estadual';\nCOMMENT ON COLUMN clients.municipal_registration IS 'Inscrição Municipal';\n",
  "010_fiscal_files.sql": "-- Migration: 010_fiscal_files\n-- Tabela de arquivos fiscais dos clientes\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\n\nCREATE TABLE IF NOT EXISTS fiscal_files (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  client_id UUID NOT NULL REFERENCES clients(id) ON DELETE CASCADE,\n  file_type VARCHAR(50) NOT NULL,\n  competence VARCHAR(7) NOT NULL, -- Formato: YYYY-MM\n  file_name VARCHAR(255) NOT NULL,\n  file_path VARCHAR(500) NOT NULL, -- Path no Supabase Storage\n  file_size BIGINT NOT NULL,\n  mime_type VARCHAR(100),\n  status VARCHAR(50) NOT NULL DEFAULT 'uploaded',\n  processing_error TEXT,\n  metadata JSONB,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW(),\n  \n  -- Validação de competência (formato YYYY-MM)\n  CONSTRAINT check_competence_format CHECK (competence ~ '^\\d{4}-\\d{2}$')\n);\n\n-- Índices\nCREATE INDEX IF NOT EXISTS idx_fiscal_files_client_id ON fiscal_files(client_id);\nCREATE INDEX IF NOT EXISTS idx_fiscal_files_competence ON fiscal_files(competence);\nCREATE INDEX IF NOT EXISTS idx_fiscal_files_status ON fiscal_files(status);\nCREATE INDEX IF NOT EXISTS idx_fiscal_files_file_type ON fiscal_files(file_type);\nCREATE INDEX IF NOT EXISTS idx_fiscal_files_client_competence ON fiscal_files(client_id, competence);\n\n-- Trigger para updated_at\nCREATE TRIGGER update_fiscal_files_updated_at \n  BEFORE UPDATE ON fiscal_files \n  FOR EACH ROW \n  EXECUTE FUNCTION update_updated_at_column();\n\n-- Comentários para documentação\nCOMMENT ON TABLE fiscal_files IS 'Arquivos fiscais enviados pelos clientes (SPED, ECD, PGDAS, etc)';\nCOMMENT ON COLUMN fiscal_files.file_type IS 'Tipo: sped, ecd, pgdas, xml, pdf, txt, outros';\nCOMMENT ON COLUMN fiscal_files.status IS 'Status: uploaded, processing, processed, error';\nCOMMENT ON COLUMN fiscal_files.competence IS 'Competência no formato YYYY-MM (ex: 2024-01)';\n",
  "011_extracted_data.sql": "-- Migration: 011_extracted_data\n-- Tabela de dados extraídos dos arquivos fiscais\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\n\nCREATE TABLE IF NOT EXISTS extracted_fiscal_data (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  fiscal_file_id UUID NOT NULL REFERENCES fiscal_files(id) ON DELETE CASCADE,\n  client_id UUID NOT NULL REFERENCES clients(id) ON DELETE CASCADE,\n  data_type VARCHAR(50) NOT NULL,\n  competence VARCHAR(7) NOT NULL, -- Formato: YYYY-MM\n  data JSONB NOT NULL,\n  created_at TIMESTAMP DEFAULT NOW(),\n  \n  -- Validação de competência (formato YYYY-MM)\n  CONSTRAINT check_competence_format CHECK (competence ~ '^\\d{4}-\\d{2}$')\n);\n\n-- Índices\nCREATE INDEX IF NOT EXISTS idx_extracted_data_fiscal_file_id ON extracted_fiscal_data(fiscal_file_id);\nCREATE INDEX IF NOT EXISTS idx_extracted_data_client_id ON extracted_fiscal_data(client_id);\nCREATE INDEX IF NOT EXISTS idx_extracted_data_data_type ON extracted_fiscal_data(data_type);\nCREATE INDEX IF NOT EXISTS idx_extracted_data_competence ON extracted_fiscal_data(competence);\nCREATE INDEX IF NOT EXISTS idx_extracted_data_client_competence ON extracted_fiscal_data(client_id, competence);\n\n-- Índice GIN para busca em JSONB\nCREATE INDEX IF NOT EXISTS idx_extracted_data_data_gin ON extracted_fiscal_data USING GIN (data);\n\n-- Comentários para documentação\nCOMMENT ON TABLE extracted_fiscal_data IS 'Dados estruturados extraídos dos arquivos fiscais';\nCOMMENT ON COLUMN extracted_fiscal_data.data_type IS 'Tipo: balance_sheet, dre, tax_liabilities, revenue, other';\nCOMMENT ON COLUMN extracted_fiscal_data.data IS 'Dados estruturados em JSONB';\nCOMMENT ON COLUMN extracted_fiscal_data.competence IS 'Competência no formato YYYY-MM (ex: 2024-01)';\n",
  "021_rating_validations.sql": "-- Migration: 021_rating_validations\n-- Tabela de validações de Rating PGFN (CAPAG)\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\n\nCREATE TABLE IF NOT EXISTS rating_validations (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  client_id UUID NOT NULL REFERENCES clients(id) ON DELETE CASCADE,\n  competence VARCHAR(7) NOT NULL, -- Formato: YYYY-MM\n  fiscal_file_id UUID REFERENCES fiscal_files(id) ON DELETE SET NULL, -- NULL para simulações\n  is_simulation BOOLEAN DEFAULT false,\n  \n  -- Dados de entrada (campos granulares)\n  input_data JSONB NOT NULL, -- Balanço e DRE usados (estrutura granular)\n  \n  -- Valores agregados calculados (para referência)\n  calculated_values JSONB, -- Valores intermediários calculados (ativo_circulante_total, etc.)\n  \n  -- Indicadores calculados\n  liquidez_corrente DECIMAL(15,4),\n  liquidez_geral DECIMAL(15,4),\n  solvencia DECIMAL(15,4),\n  \n  -- Ratings\n  rating_estimado VARCHAR(1) NOT NULL, -- A, B, C, D\n  rating_real VARCHAR(1), -- A, B, C, D (opcional)\n  \n  -- Análise\n  has_discrepancy BOOLEAN DEFAULT false,\n  discrepancy_details JSONB, -- Detalhes da discrepância\n  \n  -- Metadados\n  created_by UUID, -- Referência a users (pode ser NULL se não houver user)\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW(),\n  \n  -- Validação de competência (formato YYYY-MM)\n  CONSTRAINT check_competence_format CHECK (competence ~ '^\\d{4}-\\d{2}$'),\n  -- Validação de rating\n  CONSTRAINT check_rating_estimado CHECK (rating_estimado IN ('A', 'B', 'C', 'D')),\n  CONSTRAINT check_rating_real CHECK (rating_real IS NULL OR rating_real IN ('A', 'B', 'C', 'D'))\n);\n\n-- Índices\nCREATE INDEX IF NOT EXISTS idx_rating_validations_client_id ON rating_validations(client_id);\nCREATE INDEX IF NOT EXISTS idx_rating_validations_competence ON rating_validations(competence);\nCREATE INDEX IF NOT EXISTS idx_rating_validations_fiscal_file_id ON rating_validations(fiscal_file_id);\nCREATE INDEX IF NOT EXISTS idx_rating_validations_is_simulation ON rating_validations(is_simulation);\nCREATE INDEX IF NOT EXISTS idx_rating_validations_rating_estimado ON rating_validations(rating_estimado);\nCREATE INDEX IF NOT EXISTS idx_rating_validations_client_competence ON rating_validations(client_id, competence);\nCREATE INDEX IF NOT EXISTS idx_rating_validations_created_at ON rating_validations(created_at DESC);\n\n-- Índice GIN para busca em JSONB\nCREATE INDEX IF NOT EXISTS idx_rating_validations_input_data_gin ON rating_validations USING GIN (input_data);\nCREATE INDEX IF NOT EXISTS idx_rating_validations_calculated_values_gin ON rating_validations USING GIN (calculated_values);\n\n-- Trigger para updated_at\nCREATE TRIGGER update_rating_validations_updated_at \n  BEFORE UPDATE ON rating_validations \n  FOR EACH ROW \n  EXECUTE FUNCTION update_updated_at_column();\n\n-- Comentários para documentação\nCOMMENT ON TABLE rating_validations IS 'Validações de Rating PGFN (CAPAG) - Simulações e validações reais de ECD';\nCOMMENT ON COLUMN rating_validations.is_simulation IS 'true para simulações, false para validações reais de ECD';\nCOMMENT ON COLUMN rating_validations.input_data IS 'Dados de entrada granulares (Balanço e DRE)';\nCOMMENT ON COLUMN rating_validations.calculated_values IS 'Valores agregados calculados automaticamente (ativo_circulante_total, etc.)';\nCOMMENT ON COLUMN rating_validations.rating_estimado IS 'Rating calculado pelos indicadores (A, B, C, D)';\nCOMMENT ON COLUMN rating_validations.rating_real IS 'Rating real informado pelo usuário ou extraído da ECD';\nCOMMENT ON COLUMN rating_validations.has_discrepancy IS 'true se rating_estimado != rating_real';\nCOMMENT ON COLUMN rating_validations.competence IS 'Competência no formato YYYY-MM (ex: 2024-01)';\n",
  "024_judicial_processes.sql": "-- Migration: 024_judicial_processes\n-- Tabela de processos judiciais dos clientes (para validação de elegibilidade em editais de contencioso)\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\n\nCREATE TABLE IF NOT EXISTS judicial_processes (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  client_id UUID NOT NULL REFERENCES clients(id) ON DELETE CASCADE,\n  process_number VARCHAR(50) NOT NULL, -- Número do processo (ex: 1234567-89.2023.4.03.0001)\n  court VARCHAR(255), -- Tribunal/Órgão (ex: TRF4, STJ, etc)\n  legal_thesis VARCHAR(100) NOT NULL, -- Tese jurídica: IPI_PRACA, PRL, IRPJ_CSLL_DESMUTUALIZACAO\n  case_value NUMERIC(15, 2), -- Valor da causa (em reais)\n  start_date DATE, -- Data de início do processo\n  status VARCHAR(50) NOT NULL DEFAULT 'active', -- active, suspended, closed\n  notes TEXT, -- Observações adicionais\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW(),\n  \n  -- Validação de tese jurídica\n  CONSTRAINT check_legal_thesis CHECK (legal_thesis IN ('IPI_PRACA', 'PRL', 'IRPJ_CSLL_DESMUTUALIZACAO'))\n);\n\n-- Índices\nCREATE INDEX IF NOT EXISTS idx_judicial_processes_client_id ON judicial_processes(client_id);\nCREATE INDEX IF NOT EXISTS idx_judicial_processes_legal_thesis ON judicial_processes(legal_thesis);\nCREATE INDEX IF NOT EXISTS idx_judicial_processes_status ON judicial_processes(status);\nCREATE INDEX IF NOT EXISTS idx_judicial_processes_client_thesis ON judicial_processes(client_id, legal_thesis);\n\n-- Trigger para updated_at\nCREATE TRIGGER update_judicial_processes_updated_at \n  BEFORE UPDATE ON judicial_processes \n  FOR EACH ROW \n  EXECUTE FUNCTION update_updated_at_column();\n\n-- Comentários para documentação\nCOMMENT ON TABLE judicial_processes IS 'Processos judiciais dos clientes relacionados a teses tributárias específicas';\nCOMMENT ON COLUMN judicial_processes.legal_thesis IS 'Tese jurídica: IPI_PRACA (IPI - Conceito de Praça), PRL (Preço de Transferência), IRPJ_CSLL_DESMUTUALIZACAO (IRPJ/CSLL sobre desmutualização)';\nCOMMENT ON COLUMN judicial_processes.status IS 'Status: active (ativo), suspended (suspenso), closed (encerrado)';\nCOMMENT ON COLUMN judicial_processes.process_number IS 'Número do processo judicial (formato livre)';\n",
  "025_in_2306_simulations.sql": "-- Migration: 025_in_2306_simulations\n-- Tabela de simulações da Nova IN 2.306/2026\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\n\nCREATE TABLE IF NOT EXISTS in_2306_simulations (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  client_id UUID REFERENCES clients(id) ON DELETE SET NULL, -- Opcional para simulações sem vínculo\n  competence VARCHAR(7) NOT NULL, -- Formato: YYYY-MM\n  \n  -- Dados de entrada da simulação (estrutura flexível conforme regras da IN 2.306/2026)\n  input_data JSONB NOT NULL,\n  \n  -- Resultado da simulação (valores calculados, parcelas, condições, etc.)\n  result_data JSONB NOT NULL,\n  \n  -- Metadados\n  title VARCHAR(255), -- Título opcional da simulação\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW(),\n  \n  CONSTRAINT check_competence_format_in2306 CHECK (competence ~ '^\\d{4}-\\d{2}$')\n);\n\n-- Índices\nCREATE INDEX IF NOT EXISTS idx_in_2306_simulations_client_id ON in_2306_simulations(client_id);\nCREATE INDEX IF NOT EXISTS idx_in_2306_simulations_competence ON in_2306_simulations(competence);\nCREATE INDEX IF NOT EXISTS idx_in_2306_simulations_created_at ON in_2306_simulations(created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_in_2306_simulations_input_data_gin ON in_2306_simulations USING GIN (input_data);\nCREATE INDEX IF NOT EXISTS idx_in_2306_simulations_result_data_gin ON in_2306_simulations USING GIN (result_data);\n\n-- Trigger para updated_at\nCREATE TRIGGER update_in_2306_simulations_updated_at\n  BEFORE UPDATE ON in_2306_simulations\n  FOR EACH ROW\n  EXECUTE FUNCTION update_updated_at_column();\n\nCOMMENT ON TABLE in_2306_simulations IS 'Simulações da Nova IN 2.306/2026 - Parcelamento e condições fiscais';\nCOMMENT ON COLUMN in_2306_simulations.input_data IS 'Dados de entrada (valores, prazos, opções conforme IN 2.306/2026)';\nCOMMENT ON COLUMN in_2306_simulations.result_data IS 'Resultado da simulação (parcelas, totais, condições aplicáveis)';\n",
  "029_irpf_alta_renda.sql": "-- Migration: 029_irpf_alta_renda\n-- Tabela de simulações IRPF Alta Renda (Lei 15.270/2025)\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\n-- company_id referencia public.companies (tenant/empresa a que a simulação pertence).\n\nCREATE TABLE IF NOT EXISTS irpf_alta_renda (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  company_id UUID REFERENCES public.companies(id) ON DELETE SET NULL,\n\n  ano INTEGER NOT NULL,\n  contribuinte_nome VARCHAR(255) NOT NULL,\n  contribuinte_cpf VARCHAR(14) NOT NULL,\n  rendimentos_tributaveis NUMERIC(18, 2) NOT NULL DEFAULT 0,\n  dados_dividendos JSONB NOT NULL DEFAULT '[]',\n  base_calculo_combinada NUMERIC(18, 2) NOT NULL,\n  resultado_simulacao JSONB NOT NULL,\n\n  title VARCHAR(255),\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW(),\n\n  CONSTRAINT check_irpf_alta_renda_ano CHECK (ano >= 2020 AND ano <= 2035)\n);\n\nCREATE INDEX IF NOT EXISTS idx_irpf_alta_renda_company_id ON irpf_alta_renda(company_id);\nCREATE INDEX IF NOT EXISTS idx_irpf_alta_renda_ano ON irpf_alta_renda(ano);\nCREATE INDEX IF NOT EXISTS idx_irpf_alta_renda_created_at ON irpf_alta_renda(created_at DESC);\n\nCREATE TRIGGER update_irpf_alta_renda_updated_at\n  BEFORE UPDATE ON irpf_alta_renda\n  FOR EACH ROW\n  EXECUTE FUNCTION update_updated_at_column();\n\nCOMMENT ON TABLE irpf_alta_renda IS 'Simulações IRPF Alta Renda - Lei 15.270/2025';\nCOMMENT ON COLUMN irpf_alta_renda.dados_dividendos IS 'Array de fontes de rendimentos isentos (códigos 09 e 13)';\nCOMMENT ON COLUMN irpf_alta_renda.resultado_simulacao IS 'Resultado da simulação: faixa, alíquota, imposto, risco de retenção';\n",
  "034_irpf_alta_renda_add_company_id.sql": "-- Migration: 034_irpf_alta_renda_add_company_id\n-- Adiciona coluna company_id à tabela irpf_alta_renda no schema do tenant.\n-- A migration 029 foi aplicada antes de essa coluna existir.\nALTER TABLE irpf_alta_renda\n  ADD COLUMN IF NOT EXISTS company_id UUID REFERENCES public.companies(id) ON DELETE SET NULL;\n\nCREATE INDEX IF NOT EXISTS idx_irpf_alta_renda_company_id ON irpf_alta_renda(company_id);\n",
  "036_properties.sql": "-- Migration: 036_properties\n-- Tabelas de imóveis e transações para módulo de Gestão Imobiliária\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\n\n-- Tipo de locação: fixa (mensal) ou flexível (Airbnb/short-term)\n-- Tipo de transação: receita, despesa_dedutivel, custo_operacional\n\nCREATE TABLE IF NOT EXISTS properties (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  client_id UUID NOT NULL REFERENCES clients(id) ON DELETE CASCADE,\n  tipo_locacao VARCHAR(20) NOT NULL CHECK (tipo_locacao IN ('fixa', 'flexivel')),\n  identificador VARCHAR(255) NOT NULL,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE TABLE IF NOT EXISTS property_transactions (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  property_id UUID NOT NULL REFERENCES properties(id) ON DELETE CASCADE,\n  mes_referencia VARCHAR(7) NOT NULL CHECK (mes_referencia ~ '^\\d{4}-\\d{2}$'),\n  tipo VARCHAR(30) NOT NULL CHECK (tipo IN ('receita', 'despesa_dedutivel', 'custo_operacional')),\n  categoria VARCHAR(50) NOT NULL,\n  valor DECIMAL(15, 2) NOT NULL DEFAULT 0,\n  observacao TEXT,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\n-- Índices\nCREATE INDEX IF NOT EXISTS idx_properties_client_id ON properties(client_id);\nCREATE INDEX IF NOT EXISTS idx_properties_tipo_locacao ON properties(tipo_locacao);\nCREATE INDEX IF NOT EXISTS idx_property_transactions_property_id ON property_transactions(property_id);\nCREATE INDEX IF NOT EXISTS idx_property_transactions_mes_referencia ON property_transactions(mes_referencia);\nCREATE INDEX IF NOT EXISTS idx_property_transactions_tipo ON property_transactions(tipo);\nCREATE INDEX IF NOT EXISTS idx_property_transactions_property_mes ON property_transactions(property_id, mes_referencia);\n\n-- Triggers para updated_at\nCREATE TRIGGER update_properties_updated_at\n  BEFORE UPDATE ON properties\n  FOR EACH ROW\n  EXECUTE FUNCTION update_updated_at_column();\n\nCREATE TRIGGER update_property_transactions_updated_at\n  BEFORE UPDATE ON property_transactions\n  FOR EACH ROW\n  EXECUTE FUNCTION update_updated_at_column();\n\nCOMMENT ON TABLE properties IS 'Imóveis para gestão patrimonial e planejamento tributário';\nCOMMENT ON TABLE property_transactions IS 'Lançamentos de receita e despesa por imóvel (mensais)';\n",
  "038_property_monthly_totals.sql": "-- Migration: 038_property_monthly_totals\n-- Versão reduzida: totais mensais por tipo (locação longa e short)\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\n\n-- Adicionar modo_entrada ao property: detalhado (transações) ou reduzido (totais mensais)\nALTER TABLE properties\n  ADD COLUMN IF NOT EXISTS modo_entrada VARCHAR(20) NOT NULL DEFAULT 'detalhado'\n  CHECK (modo_entrada IN ('detalhado', 'reduzido'));\n\n-- Tabela para modo reduzido: totais mensais (locação longa + short)\nCREATE TABLE IF NOT EXISTS property_monthly_totals (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  property_id UUID NOT NULL REFERENCES properties(id) ON DELETE CASCADE,\n  mes_referencia VARCHAR(7) NOT NULL CHECK (mes_referencia ~ '^\\d{4}-\\d{2}$'),\n  receita_longa DECIMAL(15, 2) NOT NULL DEFAULT 0,\n  receita_short DECIMAL(15, 2) NOT NULL DEFAULT 0,\n  despesas_dedutiveis DECIMAL(15, 2) NOT NULL DEFAULT 0,\n  custos_operacionais DECIMAL(15, 2) NOT NULL DEFAULT 0,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW(),\n  UNIQUE(property_id, mes_referencia)\n);\n\nCREATE INDEX IF NOT EXISTS idx_property_monthly_totals_property_id ON property_monthly_totals(property_id);\nCREATE INDEX IF NOT EXISTS idx_property_monthly_totals_mes ON property_monthly_totals(mes_referencia);\n\nCREATE TRIGGER update_property_monthly_totals_updated_at\n  BEFORE UPDATE ON property_monthly_totals\n  FOR EACH ROW\n  EXECUTE FUNCTION update_updated_at_column();\n\nCOMMENT ON TABLE property_monthly_totals IS 'Totais mensais (modo reduzido): locação longa, short, despesas e custos';\nCOMMENT ON COLUMN properties.modo_entrada IS 'detalhado=transações individuais; reduzido=totais mensais';\n",
  "040_irpf_alta_renda_payload_json.sql": "-- Migration: 040_irpf_alta_renda_payload_json\n-- Adiciona coluna payload_json para armazenar simulação completa (dados de entrada + resultado).\n-- Estrutura: tipo_importacao, arquivo_nome, ano, dados, resultado_simulacao, declaracao_completa, diagnostico.\n-- Mantém colunas existentes por compatibilidade (preenchidas a partir de payload_json ou vice-versa).\n\nALTER TABLE irpf_alta_renda\nADD COLUMN IF NOT EXISTS payload_json JSONB;\n\nCOMMENT ON COLUMN irpf_alta_renda.payload_json IS 'Payload completo: tipo_importacao, arquivo_nome, dados, resultado_simulacao, declaracao_completa, diagnostico';\n",
  "045_clients_person_type.sql": "-- Migration: 045_clients_person_type\n-- Suporte a pessoa física no cadastro de clientes\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\n\n-- Tornar cnpj nullable (PF não tem CNPJ)\nALTER TABLE clients ALTER COLUMN cnpj DROP NOT NULL;\n\n-- Adicionar person_type e cpf\nALTER TABLE clients\n  ADD COLUMN IF NOT EXISTS person_type VARCHAR(2) DEFAULT 'pj',\n  ADD COLUMN IF NOT EXISTS cpf VARCHAR(14);\n\n-- Remover constraint UNIQUE(cnpj) se existir, pois agora cnpj pode ser NULL\n-- Em PostgreSQL, UNIQUE permite múltiplos NULLs, então a constraint pode permanecer\n-- Mas precisamos de unique em cpf quando preenchido\nCREATE UNIQUE INDEX IF NOT EXISTS idx_clients_cpf_unique ON clients(cpf) WHERE cpf IS NOT NULL;\n\nCOMMENT ON COLUMN clients.person_type IS 'pj = Pessoa Jurídica, pf = Pessoa Física';\nCOMMENT ON COLUMN clients.cpf IS 'CPF do cliente quando person_type = pf';\n",
  "046_property_simulations.sql": "-- Migration: 046_property_simulations\n-- Tabela de simulações do Simulador Imobiliário (PF vs PJ vs Reforma)\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\n\nCREATE TABLE IF NOT EXISTS property_simulations (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  client_id UUID REFERENCES clients(id) ON DELETE SET NULL,\n  ano INTEGER NOT NULL,\n  input_data JSONB NOT NULL,\n  result_data JSONB NOT NULL,\n  title VARCHAR(255),\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW(),\n  CONSTRAINT check_property_simulations_ano CHECK (ano >= 2020 AND ano <= 2035)\n);\n\nCREATE INDEX IF NOT EXISTS idx_property_simulations_client_id ON property_simulations(client_id);\nCREATE INDEX IF NOT EXISTS idx_property_simulations_ano ON property_simulations(ano);\nCREATE INDEX IF NOT EXISTS idx_property_simulations_created_at ON property_simulations(created_at DESC);\n\nCREATE TRIGGER update_property_simulations_updated_at\n  BEFORE UPDATE ON property_simulations\n  FOR EACH ROW\n  EXECUTE FUNCTION update_updated_at_column();\n\nCOMMENT ON TABLE property_simulations IS 'Simulações Simulador Imobiliário PF vs PJ vs Reforma 2027';\n",
  "048_rating_parcelamento_pgfn.sql": "-- Migration: 048_rating_parcelamento_pgfn\n-- Adiciona campo para armazenar dados do parcelamento PGFN junto com a simulação\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\n\n-- Adicionar coluna para armazenar dados do parcelamento PGFN\nALTER TABLE rating_validations \nADD COLUMN IF NOT EXISTS parcelamento_pgfn JSONB;\n\n-- Adicionar coluna para armazenar o comparativo calculado\nALTER TABLE rating_validations \nADD COLUMN IF NOT EXISTS comparativo_parcelamento JSONB;\n\n-- Índice GIN para busca em JSONB do parcelamento\nCREATE INDEX IF NOT EXISTS idx_rating_validations_parcelamento_pgfn_gin \nON rating_validations USING GIN (parcelamento_pgfn) \nWHERE parcelamento_pgfn IS NOT NULL;\n\n-- Comentários para documentação\nCOMMENT ON COLUMN rating_validations.parcelamento_pgfn IS 'Dados do parcelamento PGFN extraídos do Recibo de Adesão (CNPJ, modalidade, dívidas, capacidade de pagamento, consolidação, pagamento)';\nCOMMENT ON COLUMN rating_validations.comparativo_parcelamento IS 'Comparativo entre rating calculado e parcelamento PGFN (cenários, diferença financeira, fundamentação jurídica)';\n",
  "049_fiscal_sped_calibrator_rules.sql": "-- Migration: 049_fiscal_sped_calibrator_rules\n-- Regras de calibracao para classificacao de contas SPED (por tenant, opcionalmente por cliente)\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\n\nCREATE TABLE IF NOT EXISTS fiscal_sped_calibrator_rules (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  client_id UUID NULL REFERENCES clients(id) ON DELETE CASCADE,\n  pattern VARCHAR(255) NOT NULL,\n  target_module VARCHAR(50) NOT NULL DEFAULT 'simulador_in2306',\n  target_kind VARCHAR(20) NOT NULL, -- receita | deducao | retencao\n  target_field VARCHAR(100) NOT NULL,\n  confidence_override NUMERIC(5,2),\n  active BOOLEAN NOT NULL DEFAULT TRUE,\n  notes TEXT,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW(),\n  CONSTRAINT check_target_kind CHECK (target_kind IN ('receita', 'deducao', 'retencao')),\n  CONSTRAINT check_confidence_override CHECK (\n    confidence_override IS NULL OR (confidence_override >= 0 AND confidence_override <= 1)\n  )\n);\n\nCREATE INDEX IF NOT EXISTS idx_fiscal_sped_calibrator_rules_client_id\n  ON fiscal_sped_calibrator_rules(client_id);\nCREATE INDEX IF NOT EXISTS idx_fiscal_sped_calibrator_rules_active\n  ON fiscal_sped_calibrator_rules(active);\nCREATE INDEX IF NOT EXISTS idx_fiscal_sped_calibrator_rules_module\n  ON fiscal_sped_calibrator_rules(target_module);\n\nCREATE TRIGGER update_fiscal_sped_calibrator_rules_updated_at\n  BEFORE UPDATE ON fiscal_sped_calibrator_rules\n  FOR EACH ROW\n  EXECUTE FUNCTION update_updated_at_column();\n\nCOMMENT ON TABLE fiscal_sped_calibrator_rules IS\n  'Regras de calibracao da classificacao SPED para prefill de modulos';\nCOMMENT ON COLUMN fiscal_sped_calibrator_rules.client_id IS\n  'Quando NULL, regra global do tenant; quando preenchido, regra especifica do cliente';\nCOMMENT ON COLUMN fiscal_sped_calibrator_rules.pattern IS\n  'Padrao textual usado na descricao da conta para classificar';\nCOMMENT ON COLUMN fiscal_sped_calibrator_rules.target_kind IS\n  'Tipo de classificacao: receita, deducao ou retencao';\n",
  "050_properties_defaults.sql": "-- Migration: 050_properties_defaults\n-- Campos opcionais de pré-cadastro para auto-preenchimento da simulação\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\n\nALTER TABLE properties\n  ADD COLUMN IF NOT EXISTS matricula_imovel VARCHAR(100),\n  ADD COLUMN IF NOT EXISTS inscricao_iptu VARCHAR(100),\n  ADD COLUMN IF NOT EXISTS cartorio_registro VARCHAR(255),\n  ADD COLUMN IF NOT EXISTS cep VARCHAR(10),\n  ADD COLUMN IF NOT EXISTS logradouro VARCHAR(255),\n  ADD COLUMN IF NOT EXISTS numero VARCHAR(30),\n  ADD COLUMN IF NOT EXISTS complemento VARCHAR(120),\n  ADD COLUMN IF NOT EXISTS bairro VARCHAR(120),\n  ADD COLUMN IF NOT EXISTS cidade VARCHAR(120),\n  ADD COLUMN IF NOT EXISTS uf VARCHAR(2),\n  ADD COLUMN IF NOT EXISTS iptu_mensal_padrao DECIMAL(15,2),\n  ADD COLUMN IF NOT EXISTS condominio_mensal_padrao DECIMAL(15,2),\n  ADD COLUMN IF NOT EXISTS seguro_mensal_padrao DECIMAL(15,2),\n  ADD COLUMN IF NOT EXISTS camareira_mensal_padrao DECIMAL(15,2),\n  ADD COLUMN IF NOT EXISTS seguranca_mensal_padrao DECIMAL(15,2),\n  ADD COLUMN IF NOT EXISTS material_limpeza_mensal_padrao DECIMAL(15,2),\n  ADD COLUMN IF NOT EXISTS lavanderia_enxoval_mensal_padrao DECIMAL(15,2),\n  ADD COLUMN IF NOT EXISTS checkin_checkout_mensal_padrao DECIMAL(15,2),\n  ADD COLUMN IF NOT EXISTS taxas_pagamento_mensal_padrao DECIMAL(15,2),\n  ADD COLUMN IF NOT EXISTS tarifas_bancarias_mensal_padrao DECIMAL(15,2),\n  ADD COLUMN IF NOT EXISTS vacancia_mensal_padrao DECIMAL(15,2),\n  ADD COLUMN IF NOT EXISTS inadimplencia_mensal_padrao DECIMAL(15,2);\n",
  "051_properties_rent_and_nature.sql": "-- Migration: 051_properties_rent_and_nature\n-- Adiciona campos principais para simulação tributária por imóvel\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\n\nALTER TABLE properties\n  ADD COLUMN IF NOT EXISTS natureza_locacao VARCHAR(20) NOT NULL DEFAULT 'residencial',\n  ADD COLUMN IF NOT EXISTS valor_aluguel_mensal DECIMAL(15,2) NOT NULL DEFAULT 0;\n\nDO $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1\n    FROM pg_constraint\n    WHERE conname = 'properties_natureza_locacao_check'\n  ) THEN\n    ALTER TABLE properties\n      ADD CONSTRAINT properties_natureza_locacao_check\n      CHECK (natureza_locacao IN ('residencial', 'nao_residencial'));\n  END IF;\nEND $$;\n",
  "052_property_transactions_fiscal_credit.sql": "-- Migration: 052_property_transactions_fiscal_credit\n-- Metadados fiscais para classificar crédito IBS/CBS em custos operacionais\n-- Esta migration roda em schemas de tenant (tenant_{company_id})\n\nALTER TABLE property_transactions\n  ADD COLUMN IF NOT EXISTS gera_credito_ibs_cbs BOOLEAN,\n  ADD COLUMN IF NOT EXISTS tipo_credito VARCHAR(20)\n    CHECK (tipo_credito IN ('insumo', 'uso_consumo', 'nao_creditavel'));\n\nCOMMENT ON COLUMN property_transactions.gera_credito_ibs_cbs\n  IS 'Indica se o lançamento foi classificado como potencial gerador de crédito IBS/CBS.';\nCOMMENT ON COLUMN property_transactions.tipo_credito\n  IS 'Classificação fiscal do crédito: insumo, uso_consumo ou nao_creditavel.';\n",
  "053_property_simulations_simulation_kind.sql": "-- Migration: 053_property_simulations_simulation_kind\n-- Distingue simulações do Simulador Locação PF×PJ vs Ganho de Capital (imóvel)\n\nALTER TABLE property_simulations\n  ADD COLUMN IF NOT EXISTS simulation_kind TEXT NOT NULL DEFAULT 'locacao_pf_pj';\n\nALTER TABLE property_simulations\n  DROP CONSTRAINT IF EXISTS check_property_simulations_simulation_kind;\n\nALTER TABLE property_simulations\n  ADD CONSTRAINT check_property_simulations_simulation_kind\n  CHECK (simulation_kind IN ('locacao_pf_pj', 'ganho_capital_imovel'));\n\nCREATE INDEX IF NOT EXISTS idx_property_simulations_kind_created\n  ON property_simulations (simulation_kind, created_at DESC);\n\nCOMMENT ON COLUMN property_simulations.simulation_kind IS 'locacao_pf_pj: Simulador locação; ganho_capital_imovel: venda / ganho de capital';\n",
  "054_distribuicao_lucros_simulations.sql": "-- Migration: 054_distribuicao_lucros_simulations\n-- Simulações: investimento na PJ x retenção na PF (Lei 15.270/2025)\n-- Schema tenant (tenant_{company_id})\n\nCREATE TABLE IF NOT EXISTS distribuicao_lucros_simulations (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  client_id UUID NOT NULL REFERENCES clients(id) ON DELETE CASCADE,\n  input_data JSONB NOT NULL,\n  result_data JSONB NOT NULL,\n  title VARCHAR(255),\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_distribuicao_lucros_simulations_client_id ON distribuicao_lucros_simulations(client_id);\nCREATE INDEX IF NOT EXISTS idx_distribuicao_lucros_simulations_created_at ON distribuicao_lucros_simulations(created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_distribuicao_lucros_simulations_input_data_gin ON distribuicao_lucros_simulations USING GIN (input_data);\nCREATE INDEX IF NOT EXISTS idx_distribuicao_lucros_simulations_result_data_gin ON distribuicao_lucros_simulations USING GIN (result_data);\n\nCREATE TRIGGER update_distribuicao_lucros_simulations_updated_at\n  BEFORE UPDATE ON distribuicao_lucros_simulations\n  FOR EACH ROW\n  EXECUTE FUNCTION update_updated_at_column();\n\nCOMMENT ON TABLE distribuicao_lucros_simulations IS 'Simulações investimento PJ x retenção PF (Lei 15.270/2025)';\nCOMMENT ON COLUMN distribuicao_lucros_simulations.input_data IS 'Parâmetros: valor, meses, irpjRate, appKey';\nCOMMENT ON COLUMN distribuicao_lucros_simulations.result_data IS 'Resultado completo da runDistribuicaoLucrosSimulation';\n",
  "069_gestao_imobiliaria_contabil.sql": "-- Migration: 069_gestao_imobiliaria_contabil\n-- Camada contábil-operacional da Gestão Imobiliária (contratos, ledger, extratos, operação).\n-- Roda em schemas de tenant (tenant_{company_id}). Convive com as tabelas tributárias\n-- existentes (properties / property_transactions / property_simulations) sem alterá-las.\n--\n-- Princípio: property_transactions continua sendo o diário TRIBUTÁRIO (competência p/ IR);\n-- property_ledger_entries é o livro OPERACIONAL de caixa/competência com vencimento e status.\n\n-- ==========================================================================\n-- 1) Inquilinos\n-- ==========================================================================\nCREATE TABLE IF NOT EXISTS property_tenants (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  client_id UUID REFERENCES clients(id) ON DELETE SET NULL,\n  nome VARCHAR(255) NOT NULL,\n  documento VARCHAR(20),\n  tipo_pessoa VARCHAR(2) NOT NULL DEFAULT 'pf' CHECK (tipo_pessoa IN ('pf', 'pj')),\n  email VARCHAR(255),\n  telefone VARCHAR(30),\n  observacao TEXT,\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_property_tenants_client_id ON property_tenants(client_id);\nCREATE INDEX IF NOT EXISTS idx_property_tenants_nome ON property_tenants(nome);\n\n-- ==========================================================================\n-- 2) Contratos de locação\n-- ==========================================================================\nCREATE TABLE IF NOT EXISTS property_leases (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  property_id UUID NOT NULL REFERENCES properties(id) ON DELETE CASCADE,\n  tenant_id UUID REFERENCES property_tenants(id) ON DELETE SET NULL,\n  data_inicio DATE NOT NULL,\n  data_fim DATE,\n  valor_aluguel DECIMAL(15, 2) NOT NULL DEFAULT 0,\n  dia_vencimento INTEGER NOT NULL DEFAULT 10 CHECK (dia_vencimento BETWEEN 1 AND 31),\n  indice_reajuste VARCHAR(20) NOT NULL DEFAULT 'IPCA' CHECK (indice_reajuste IN ('IPCA', 'IGPM', 'INPC', 'OUTRO', 'NENHUM')),\n  status VARCHAR(20) NOT NULL DEFAULT 'ativo' CHECK (status IN ('ativo', 'encerrado', 'rascunho', 'inadimplente')),\n  observacao TEXT,\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_property_leases_property_id ON property_leases(property_id);\nCREATE INDEX IF NOT EXISTS idx_property_leases_tenant_id ON property_leases(tenant_id);\nCREATE INDEX IF NOT EXISTS idx_property_leases_status ON property_leases(status);\nCREATE INDEX IF NOT EXISTS idx_property_leases_data_fim ON property_leases(data_fim);\n\n-- Reajustes e aditivos contratuais\nCREATE TABLE IF NOT EXISTS property_lease_amendments (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  lease_id UUID NOT NULL REFERENCES property_leases(id) ON DELETE CASCADE,\n  tipo VARCHAR(20) NOT NULL DEFAULT 'reajuste' CHECK (tipo IN ('reajuste', 'aditivo', 'renovacao')),\n  data_evento DATE NOT NULL,\n  indice_aplicado VARCHAR(20),\n  percentual DECIMAL(8, 4),\n  valor_anterior DECIMAL(15, 2),\n  valor_novo DECIMAL(15, 2),\n  descricao TEXT,\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_property_lease_amendments_lease_id ON property_lease_amendments(lease_id);\n\n-- Garantias e depósitos\nCREATE TABLE IF NOT EXISTS property_guarantees (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  lease_id UUID NOT NULL REFERENCES property_leases(id) ON DELETE CASCADE,\n  tipo VARCHAR(30) NOT NULL CHECK (tipo IN ('caucao', 'fiador', 'seguro_fianca', 'titulo_capitalizacao', 'outro')),\n  valor DECIMAL(15, 2),\n  descricao TEXT,\n  status VARCHAR(20) NOT NULL DEFAULT 'ativa' CHECK (status IN ('ativa', 'devolvida', 'executada', 'encerrada')),\n  data_devolucao DATE,\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_property_guarantees_lease_id ON property_guarantees(lease_id);\n\n-- ==========================================================================\n-- 3) Livro financeiro operacional (contas a receber / pagar por imóvel)\n-- ==========================================================================\nCREATE TABLE IF NOT EXISTS property_ledger_entries (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  property_id UUID NOT NULL REFERENCES properties(id) ON DELETE CASCADE,\n  lease_id UUID REFERENCES property_leases(id) ON DELETE SET NULL,\n  competencia VARCHAR(7) NOT NULL CHECK (competencia ~ '^\\d{4}-\\d{2}$'),\n  vencimento DATE NOT NULL,\n  natureza VARCHAR(10) NOT NULL CHECK (natureza IN ('receita', 'despesa')),\n  categoria VARCHAR(60) NOT NULL,\n  descricao TEXT,\n  valor DECIMAL(15, 2) NOT NULL DEFAULT 0,\n  status VARCHAR(20) NOT NULL DEFAULT 'previsto' CHECK (status IN ('previsto', 'confirmado', 'pago', 'atrasado', 'cancelado')),\n  paid_at DATE,\n  recurring_rule_id UUID,\n  charge_id UUID,\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_property_ledger_property_id ON property_ledger_entries(property_id);\nCREATE INDEX IF NOT EXISTS idx_property_ledger_lease_id ON property_ledger_entries(lease_id);\nCREATE INDEX IF NOT EXISTS idx_property_ledger_competencia ON property_ledger_entries(competencia);\nCREATE INDEX IF NOT EXISTS idx_property_ledger_status ON property_ledger_entries(status);\nCREATE INDEX IF NOT EXISTS idx_property_ledger_vencimento ON property_ledger_entries(vencimento);\n\n-- Regras de recorrência (geram lançamentos por competência)\nCREATE TABLE IF NOT EXISTS property_recurring_rules (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  property_id UUID NOT NULL REFERENCES properties(id) ON DELETE CASCADE,\n  lease_id UUID REFERENCES property_leases(id) ON DELETE SET NULL,\n  natureza VARCHAR(10) NOT NULL CHECK (natureza IN ('receita', 'despesa')),\n  categoria VARCHAR(60) NOT NULL,\n  descricao TEXT,\n  valor DECIMAL(15, 2) NOT NULL DEFAULT 0,\n  dia_vencimento INTEGER NOT NULL DEFAULT 10 CHECK (dia_vencimento BETWEEN 1 AND 31),\n  ativo BOOLEAN NOT NULL DEFAULT true,\n  inicio_competencia VARCHAR(7) CHECK (inicio_competencia ~ '^\\d{4}-\\d{2}$'),\n  fim_competencia VARCHAR(7) CHECK (fim_competencia ~ '^\\d{4}-\\d{2}$'),\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_property_recurring_property_id ON property_recurring_rules(property_id);\nCREATE INDEX IF NOT EXISTS idx_property_recurring_ativo ON property_recurring_rules(ativo);\n\n-- ==========================================================================\n-- 4) Documentos e anexos por imóvel/contrato\n-- ==========================================================================\nCREATE TABLE IF NOT EXISTS property_documents (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  property_id UUID REFERENCES properties(id) ON DELETE CASCADE,\n  lease_id UUID REFERENCES property_leases(id) ON DELETE CASCADE,\n  categoria VARCHAR(40) NOT NULL DEFAULT 'outro',\n  nome_arquivo VARCHAR(255) NOT NULL,\n  mime_type VARCHAR(120),\n  tamanho_bytes BIGINT,\n  storage_key VARCHAR(500),\n  storage_status VARCHAR(20) NOT NULL DEFAULT 'em_criacao' CHECK (storage_status IN ('em_criacao', 'armazenado', 'erro')),\n  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_property_documents_property_id ON property_documents(property_id);\nCREATE INDEX IF NOT EXISTS idx_property_documents_lease_id ON property_documents(lease_id);\n\n-- ==========================================================================\n-- 5) Prestação de contas: links read-only por token\n-- ==========================================================================\nCREATE TABLE IF NOT EXISTS property_statement_shares (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  client_id UUID NOT NULL REFERENCES clients(id) ON DELETE CASCADE,\n  token_hash VARCHAR(128) NOT NULL UNIQUE,\n  property_ids JSONB NOT NULL DEFAULT '[]'::jsonb,\n  period_from VARCHAR(7) NOT NULL CHECK (period_from ~ '^\\d{4}-\\d{2}$'),\n  period_to VARCHAR(7) NOT NULL CHECK (period_to ~ '^\\d{4}-\\d{2}$'),\n  title VARCHAR(255),\n  expires_at TIMESTAMP NOT NULL,\n  revoked_at TIMESTAMP,\n  last_accessed_at TIMESTAMP,\n  access_count INTEGER NOT NULL DEFAULT 0,\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_property_statement_shares_client_id ON property_statement_shares(client_id);\nCREATE INDEX IF NOT EXISTS idx_property_statement_shares_token ON property_statement_shares(token_hash);\n\n-- ==========================================================================\n-- 6) Propriedade fracionada (multi-proprietário)\n-- ==========================================================================\nCREATE TABLE IF NOT EXISTS property_ownership_shares (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  property_id UUID NOT NULL REFERENCES properties(id) ON DELETE CASCADE,\n  client_id UUID REFERENCES clients(id) ON DELETE SET NULL,\n  nome_proprietario VARCHAR(255) NOT NULL,\n  documento VARCHAR(20),\n  percentual DECIMAL(7, 4) NOT NULL DEFAULT 100 CHECK (percentual >= 0 AND percentual <= 100),\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_property_ownership_shares_property_id ON property_ownership_shares(property_id);\n\n-- ==========================================================================\n-- 7) Operação interna: fornecedores, manutenções, vistorias, inventário\n-- ==========================================================================\nCREATE TABLE IF NOT EXISTS property_vendors (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  nome VARCHAR(255) NOT NULL,\n  documento VARCHAR(20),\n  categoria VARCHAR(60),\n  email VARCHAR(255),\n  telefone VARCHAR(30),\n  observacao TEXT,\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_property_vendors_nome ON property_vendors(nome);\n\nCREATE TABLE IF NOT EXISTS property_maintenance_tickets (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  property_id UUID NOT NULL REFERENCES properties(id) ON DELETE CASCADE,\n  vendor_id UUID REFERENCES property_vendors(id) ON DELETE SET NULL,\n  titulo VARCHAR(255) NOT NULL,\n  descricao TEXT,\n  status VARCHAR(20) NOT NULL DEFAULT 'aberto' CHECK (status IN ('aberto', 'em_andamento', 'aguardando_aprovacao', 'concluido', 'cancelado')),\n  prioridade VARCHAR(10) NOT NULL DEFAULT 'media' CHECK (prioridade IN ('baixa', 'media', 'alta')),\n  valor_orcado DECIMAL(15, 2),\n  valor_final DECIMAL(15, 2),\n  aberto_em DATE NOT NULL DEFAULT CURRENT_DATE,\n  concluido_em DATE,\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_property_maintenance_property_id ON property_maintenance_tickets(property_id);\nCREATE INDEX IF NOT EXISTS idx_property_maintenance_status ON property_maintenance_tickets(status);\n\nCREATE TABLE IF NOT EXISTS property_inspections (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  property_id UUID NOT NULL REFERENCES properties(id) ON DELETE CASCADE,\n  lease_id UUID REFERENCES property_leases(id) ON DELETE SET NULL,\n  tipo VARCHAR(20) NOT NULL DEFAULT 'entrada' CHECK (tipo IN ('entrada', 'saida', 'periodica')),\n  data_vistoria DATE NOT NULL DEFAULT CURRENT_DATE,\n  responsavel VARCHAR(255),\n  checklist JSONB NOT NULL DEFAULT '[]'::jsonb,\n  observacao TEXT,\n  status VARCHAR(20) NOT NULL DEFAULT 'rascunho' CHECK (status IN ('rascunho', 'concluida', 'assinada')),\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_property_inspections_property_id ON property_inspections(property_id);\n\nCREATE TABLE IF NOT EXISTS property_inventory_items (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  property_id UUID NOT NULL REFERENCES properties(id) ON DELETE CASCADE,\n  nome VARCHAR(255) NOT NULL,\n  quantidade INTEGER NOT NULL DEFAULT 1,\n  estado_conservacao VARCHAR(20) NOT NULL DEFAULT 'bom' CHECK (estado_conservacao IN ('novo', 'bom', 'regular', 'ruim', 'inservivel')),\n  valor_estimado DECIMAL(15, 2),\n  observacao TEXT,\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_property_inventory_property_id ON property_inventory_items(property_id);\n\n-- ==========================================================================\n-- 8) Integrações externas (estrutura pronta, status \"em_criacao\")\n-- ==========================================================================\nCREATE TABLE IF NOT EXISTS property_payment_charges (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  ledger_entry_id UUID REFERENCES property_ledger_entries(id) ON DELETE SET NULL,\n  property_id UUID NOT NULL REFERENCES properties(id) ON DELETE CASCADE,\n  metodo VARCHAR(20) NOT NULL DEFAULT 'boleto' CHECK (metodo IN ('boleto', 'pix')),\n  valor DECIMAL(15, 2) NOT NULL DEFAULT 0,\n  vencimento DATE NOT NULL,\n  descricao TEXT,\n  -- provider_status permanece 'em_criacao' até integrar provedor externo real\n  provider_status VARCHAR(20) NOT NULL DEFAULT 'em_criacao' CHECK (provider_status IN ('em_criacao', 'emitido', 'pago', 'cancelado', 'erro')),\n  provider_reference VARCHAR(255),\n  linha_digitavel VARCHAR(120),\n  pix_copia_cola TEXT,\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_property_payment_charges_property_id ON property_payment_charges(property_id);\nCREATE INDEX IF NOT EXISTS idx_property_payment_charges_status ON property_payment_charges(provider_status);\n\nCREATE TABLE IF NOT EXISTS property_bank_import_batches (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  referencia VARCHAR(120) NOT NULL,\n  status VARCHAR(20) NOT NULL DEFAULT 'em_criacao' CHECK (status IN ('em_criacao', 'processado', 'conciliado', 'erro')),\n  total_linhas INTEGER NOT NULL DEFAULT 0,\n  total_conciliado INTEGER NOT NULL DEFAULT 0,\n  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE TABLE IF NOT EXISTS property_bank_import_lines (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  batch_id UUID NOT NULL REFERENCES property_bank_import_batches(id) ON DELETE CASCADE,\n  data_movimento DATE,\n  descricao TEXT,\n  valor DECIMAL(15, 2) NOT NULL DEFAULT 0,\n  ledger_entry_id UUID REFERENCES property_ledger_entries(id) ON DELETE SET NULL,\n  status VARCHAR(20) NOT NULL DEFAULT 'pendente' CHECK (status IN ('pendente', 'conciliado', 'ignorado')),\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_property_bank_import_lines_batch_id ON property_bank_import_lines(batch_id);\n\n-- Comunicação (outbox): avisos/extratos por e-mail/WhatsApp (envio real = \"em_criacao\")\nCREATE TABLE IF NOT EXISTS property_communications (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  client_id UUID REFERENCES clients(id) ON DELETE SET NULL,\n  property_id UUID REFERENCES properties(id) ON DELETE SET NULL,\n  canal VARCHAR(20) NOT NULL DEFAULT 'email' CHECK (canal IN ('email', 'whatsapp')),\n  assunto VARCHAR(255),\n  mensagem TEXT,\n  destinatario VARCHAR(255),\n  status VARCHAR(20) NOT NULL DEFAULT 'em_criacao' CHECK (status IN ('em_criacao', 'agendado', 'enviado', 'erro')),\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_property_communications_client_id ON property_communications(client_id);\n\n-- ==========================================================================\n-- Triggers de updated_at\n-- ==========================================================================\nCREATE TRIGGER update_property_tenants_updated_at BEFORE UPDATE ON property_tenants FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_property_leases_updated_at BEFORE UPDATE ON property_leases FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_property_lease_amendments_updated_at BEFORE UPDATE ON property_lease_amendments FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_property_guarantees_updated_at BEFORE UPDATE ON property_guarantees FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_property_ledger_entries_updated_at BEFORE UPDATE ON property_ledger_entries FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_property_recurring_rules_updated_at BEFORE UPDATE ON property_recurring_rules FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_property_documents_updated_at BEFORE UPDATE ON property_documents FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_property_statement_shares_updated_at BEFORE UPDATE ON property_statement_shares FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_property_ownership_shares_updated_at BEFORE UPDATE ON property_ownership_shares FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_property_vendors_updated_at BEFORE UPDATE ON property_vendors FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_property_maintenance_tickets_updated_at BEFORE UPDATE ON property_maintenance_tickets FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_property_inspections_updated_at BEFORE UPDATE ON property_inspections FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_property_inventory_items_updated_at BEFORE UPDATE ON property_inventory_items FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_property_payment_charges_updated_at BEFORE UPDATE ON property_payment_charges FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_property_bank_import_batches_updated_at BEFORE UPDATE ON property_bank_import_batches FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_property_bank_import_lines_updated_at BEFORE UPDATE ON property_bank_import_lines FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_property_communications_updated_at BEFORE UPDATE ON property_communications FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\n\nCOMMENT ON TABLE property_ledger_entries IS 'Livro financeiro operacional (AR/AP) por imóvel: competência, vencimento e ciclo de pagamento';\nCOMMENT ON TABLE property_statement_shares IS 'Links read-only de prestação de contas, com escopo, expiração e revogação';\nCOMMENT ON TABLE property_payment_charges IS 'Cobranças boleto/PIX. provider_status=em_criacao até integrar provedor externo real';\n",
  "071_expense_mapping.sql": "-- Migration: 071_expense_mapping\n-- Módulo Mapeamento de Despesas PF -> PJ (pejotização): diagnóstico normalizado.\n-- Roda em schemas de tenant (tenant_{company_id}).\n--\n-- Framing: ferramenta contábil/advocacia. Classificação calculada no servidor a partir\n-- das respostas + versão do catálogo. IBS/CBS é apenas critério/alerta (segunda lente),\n-- nunca promessa automática de crédito.\n\n-- ==========================================================================\n-- 1) Catálogo versionado (categorias, perguntas e regras)\n-- ==========================================================================\nCREATE TABLE IF NOT EXISTS expense_mapping_catalog_versions (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  version VARCHAR(50) NOT NULL UNIQUE,\n  is_active BOOLEAN NOT NULL DEFAULT false,\n  categories JSONB NOT NULL DEFAULT '[]'::jsonb,\n  published_at TIMESTAMP,\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_expense_catalog_active ON expense_mapping_catalog_versions(is_active);\n\n-- ==========================================================================\n-- 2) Diagnóstico (cabeçalho)\n-- ==========================================================================\nCREATE TABLE IF NOT EXISTS expense_mapping_diagnoses (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  client_id UUID NOT NULL REFERENCES clients(id) ON DELETE CASCADE,\n  title VARCHAR(255),\n  reference_year INTEGER NOT NULL,\n  activity VARCHAR(255),\n  tax_regime VARCHAR(40) NOT NULL DEFAULT 'simples_nacional'\n    CHECK (tax_regime IN ('simples_nacional', 'lucro_presumido', 'lucro_real', 'mei', 'outro')),\n  ibs_cbs_treatment VARCHAR(40) NOT NULL DEFAULT 'nao_avaliar'\n    CHECK (ibs_cbs_treatment IN ('regime_regular', 'simples_por_dentro', 'avaliar_por_fora', 'nao_avaliar')),\n  objective TEXT,\n  reviewer_user_id UUID,\n  status VARCHAR(20) NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'in_review', 'completed', 'archived')),\n  rules_version VARCHAR(50) NOT NULL,\n  totals JSONB NOT NULL DEFAULT '{}'::jsonb,\n  result_snapshot JSONB,\n  completed_at TIMESTAMP,\n  completed_by UUID,\n  created_by UUID,\n  updated_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_expense_diagnoses_client_id ON expense_mapping_diagnoses(client_id);\nCREATE INDEX IF NOT EXISTS idx_expense_diagnoses_status ON expense_mapping_diagnoses(status);\nCREATE INDEX IF NOT EXISTS idx_expense_diagnoses_year ON expense_mapping_diagnoses(reference_year);\nCREATE INDEX IF NOT EXISTS idx_expense_diagnoses_created_at ON expense_mapping_diagnoses(created_at DESC);\n\n-- ==========================================================================\n-- 3) Respostas do questionário\n-- ==========================================================================\nCREATE TABLE IF NOT EXISTS expense_mapping_answers (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  diagnosis_id UUID NOT NULL REFERENCES expense_mapping_diagnoses(id) ON DELETE CASCADE,\n  category_key VARCHAR(60) NOT NULL,\n  question_key VARCHAR(80) NOT NULL,\n  answer JSONB NOT NULL DEFAULT '{}'::jsonb,\n  catalog_version VARCHAR(50) NOT NULL,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_expense_answers_diagnosis_id ON expense_mapping_answers(diagnosis_id);\nCREATE UNIQUE INDEX IF NOT EXISTS uq_expense_answers_diag_question ON expense_mapping_answers(diagnosis_id, category_key, question_key);\n\n-- ==========================================================================\n-- 4) Itens de despesa classificados\n-- ==========================================================================\nCREATE TABLE IF NOT EXISTS expense_mapping_items (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  diagnosis_id UUID NOT NULL REFERENCES expense_mapping_diagnoses(id) ON DELETE CASCADE,\n  category_key VARCHAR(60) NOT NULL,\n  label VARCHAR(255) NOT NULL,\n  monthly_amount DECIMAL(15, 2) NOT NULL DEFAULT 0,\n  annual_amount DECIMAL(15, 2) NOT NULL DEFAULT 0,\n  business_use_pct DECIMAL(5, 2) NOT NULL DEFAULT 0,\n  current_payer VARCHAR(20) NOT NULL DEFAULT 'pf' CHECK (current_payer IN ('pf', 'pj', 'misto')),\n  pf_pj_lens VARCHAR(20) NOT NULL DEFAULT 'organize' CHECK (pf_pj_lens IN ('migrate', 'organize', 'defer', 'avoid')),\n  credit_lens VARCHAR(20) NOT NULL DEFAULT 'na' CHECK (credit_lens IN ('potential', 'conditioned', 'none', 'na')),\n  classification VARCHAR(30) NOT NULL DEFAULT 'condicionado'\n    CHECK (classification IN ('potencial', 'condicionado', 'rateio', 'nao_recomendado')),\n  criteria JSONB NOT NULL DEFAULT '{}'::jsonb,\n  foundation_refs JSONB NOT NULL DEFAULT '[]'::jsonb,\n  notes TEXT,\n  sort_order INTEGER NOT NULL DEFAULT 0,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_expense_items_diagnosis_id ON expense_mapping_items(diagnosis_id);\nCREATE INDEX IF NOT EXISTS idx_expense_items_classification ON expense_mapping_items(classification);\n\n-- ==========================================================================\n-- 5) Pendências e plano de ação\n-- ==========================================================================\nCREATE TABLE IF NOT EXISTS expense_mapping_pendencies (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  diagnosis_id UUID NOT NULL REFERENCES expense_mapping_diagnoses(id) ON DELETE CASCADE,\n  item_id UUID REFERENCES expense_mapping_items(id) ON DELETE CASCADE,\n  tipo VARCHAR(40) NOT NULL DEFAULT 'documento',\n  titulo VARCHAR(255) NOT NULL,\n  descricao TEXT,\n  status VARCHAR(20) NOT NULL DEFAULT 'pendente' CHECK (status IN ('pendente', 'em_andamento', 'resolvida', 'descartada')),\n  due_at DATE,\n  owner_user_id UUID,\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_expense_pendencies_diagnosis_id ON expense_mapping_pendencies(diagnosis_id);\nCREATE INDEX IF NOT EXISTS idx_expense_pendencies_status ON expense_mapping_pendencies(status);\n\nCREATE TABLE IF NOT EXISTS expense_mapping_action_steps (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  item_id UUID NOT NULL REFERENCES expense_mapping_items(id) ON DELETE CASCADE,\n  step_order INTEGER NOT NULL DEFAULT 0,\n  description TEXT NOT NULL,\n  status VARCHAR(20) NOT NULL DEFAULT 'pendente' CHECK (status IN ('pendente', 'em_andamento', 'concluido')),\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_expense_action_steps_item_id ON expense_mapping_action_steps(item_id);\n\n-- ==========================================================================\n-- 6) Evidências (anexos)\n-- ==========================================================================\nCREATE TABLE IF NOT EXISTS expense_mapping_evidence (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  diagnosis_id UUID NOT NULL REFERENCES expense_mapping_diagnoses(id) ON DELETE CASCADE,\n  item_id UUID REFERENCES expense_mapping_items(id) ON DELETE CASCADE,\n  pendency_id UUID REFERENCES expense_mapping_pendencies(id) ON DELETE SET NULL,\n  kind VARCHAR(30) NOT NULL DEFAULT 'outro' CHECK (kind IN ('nfe', 'contrato', 'agenda', 'extrato', 'foto', 'outro')),\n  nome_arquivo VARCHAR(255) NOT NULL,\n  mime_type VARCHAR(120),\n  tamanho_bytes BIGINT,\n  storage_key VARCHAR(500),\n  storage_status VARCHAR(20) NOT NULL DEFAULT 'em_criacao' CHECK (storage_status IN ('em_criacao', 'armazenado', 'erro')),\n  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_expense_evidence_diagnosis_id ON expense_mapping_evidence(diagnosis_id);\nCREATE INDEX IF NOT EXISTS idx_expense_evidence_item_id ON expense_mapping_evidence(item_id);\n\n-- ==========================================================================\n-- 7) Auditoria de mutações\n-- ==========================================================================\nCREATE TABLE IF NOT EXISTS expense_mapping_audit_events (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  diagnosis_id UUID REFERENCES expense_mapping_diagnoses(id) ON DELETE CASCADE,\n  entity_type VARCHAR(40) NOT NULL,\n  entity_id UUID,\n  action VARCHAR(30) NOT NULL,\n  actor_user_id UUID,\n  before_data JSONB,\n  after_data JSONB,\n  created_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_expense_audit_diagnosis_id ON expense_mapping_audit_events(diagnosis_id);\n\n-- ==========================================================================\n-- 8) Importação documental (upload + matching manual)\n-- ==========================================================================\nCREATE TABLE IF NOT EXISTS expense_mapping_import_batches (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  diagnosis_id UUID REFERENCES expense_mapping_diagnoses(id) ON DELETE CASCADE,\n  referencia VARCHAR(120) NOT NULL,\n  status VARCHAR(20) NOT NULL DEFAULT 'aberto' CHECK (status IN ('aberto', 'processado', 'concluido', 'erro')),\n  total_linhas INTEGER NOT NULL DEFAULT 0,\n  total_vinculado INTEGER NOT NULL DEFAULT 0,\n  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_expense_import_diagnosis_id ON expense_mapping_import_batches(diagnosis_id);\n\n-- ==========================================================================\n-- Triggers de updated_at\n-- ==========================================================================\nCREATE TRIGGER update_expense_catalog_versions_updated_at BEFORE UPDATE ON expense_mapping_catalog_versions FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_expense_diagnoses_updated_at BEFORE UPDATE ON expense_mapping_diagnoses FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_expense_answers_updated_at BEFORE UPDATE ON expense_mapping_answers FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_expense_items_updated_at BEFORE UPDATE ON expense_mapping_items FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_expense_pendencies_updated_at BEFORE UPDATE ON expense_mapping_pendencies FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_expense_action_steps_updated_at BEFORE UPDATE ON expense_mapping_action_steps FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_expense_evidence_updated_at BEFORE UPDATE ON expense_mapping_evidence FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_expense_import_batches_updated_at BEFORE UPDATE ON expense_mapping_import_batches FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\n\nCOMMENT ON TABLE expense_mapping_diagnoses IS 'Diagnóstico PF->PJ por cliente/ano; classificação calculada no servidor';\nCOMMENT ON TABLE expense_mapping_items IS 'Despesas classificadas (potencial|condicionado|rateio|nao_recomendado) com duas lentes: PF->PJ e IBS/CBS';\nCOMMENT ON COLUMN expense_mapping_diagnoses.ibs_cbs_treatment IS 'IBS/CBS é segunda lente/alerta; sem promessa automática de crédito';\n",
  "074_simulation_share_tokens.sql": "-- Migration: 074_simulation_share_tokens\n-- Tenant-side: armazena dados do share de simulação\n-- Public-side: lookup rápido sem auth\n\n-- Tabela TENANT\nCREATE TABLE IF NOT EXISTS property_simulation_shares (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  simulation_id UUID NOT NULL REFERENCES property_simulations(id) ON DELETE CASCADE,\n  simulation_kind VARCHAR(50) NOT NULL DEFAULT 'locacao',\n  token_hash VARCHAR(128) NOT NULL UNIQUE,\n  title VARCHAR(255),\n  expires_at TIMESTAMP NOT NULL,\n  revoked_at TIMESTAMP,\n  access_count INTEGER NOT NULL DEFAULT 0,\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_property_simulation_shares_simulation\n  ON property_simulation_shares(simulation_id);\nCREATE INDEX IF NOT EXISTS idx_property_simulation_shares_token\n  ON property_simulation_shares(token_hash);\n",
  "076_properties_regime_tributario.sql": "-- Adiciona regime tributário escolhido e cache do resultado da simulação rápida\nALTER TABLE properties ADD COLUMN IF NOT EXISTS regime_tributario VARCHAR(10);\nALTER TABLE properties ADD COLUMN IF NOT EXISTS ultimo_resultado_simulacao JSONB;\n",
  "077_leases_regime_tributario.sql": "-- Adiciona regime tributário, cache de simulação e campos de imobiliária nos contratos\nALTER TABLE property_leases ADD COLUMN IF NOT EXISTS regime_tributario VARCHAR(10);\nALTER TABLE property_leases ADD COLUMN IF NOT EXISTS ultimo_resultado_simulacao JSONB;\nALTER TABLE property_leases ADD COLUMN IF NOT EXISTS tem_imobiliaria BOOLEAN NOT NULL DEFAULT FALSE;\nALTER TABLE property_leases ADD COLUMN IF NOT EXISTS imobiliaria_tipo VARCHAR(10) CHECK (imobiliaria_tipo IN ('percentual', 'fixo'));\nALTER TABLE property_leases ADD COLUMN IF NOT EXISTS imobiliaria_valor DECIMAL(15, 2) DEFAULT 0;\n",
  "078_simulation_shares_generic.sql": "-- Migration: 078_simulation_shares_generic\n-- Tabela genérica de shares de simulação (tenant) + lookup público\n-- Suporta todos os tipos: in_2306, irpf_alta_renda, distribuicao_lucros\n\n-- Tabela no schema do tenant\nCREATE TABLE IF NOT EXISTS simulation_shares (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  simulation_type VARCHAR(50) NOT NULL,\n  simulation_id UUID NOT NULL,\n  snapshot_data JSONB NOT NULL,\n  token_hash VARCHAR(128) UNIQUE NOT NULL,\n  title VARCHAR(255),\n  expires_at TIMESTAMP NOT NULL,\n  revoked_at TIMESTAMP,\n  access_count INT NOT NULL DEFAULT 0,\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_simulation_shares_token ON simulation_shares(token_hash);\nCREATE INDEX IF NOT EXISTS idx_simulation_shares_type_sim ON simulation_shares(simulation_type, simulation_id);\n",
  "080_comparativo_regimes_simulations.sql": "CREATE TABLE IF NOT EXISTS comparativo_regimes_simulations (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  client_id UUID REFERENCES clients(id),\n  ano INT NOT NULL,\n  title VARCHAR(255),\n  input_data JSONB NOT NULL,\n  result_data JSONB NOT NULL,\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW(),\n  updated_at TIMESTAMP DEFAULT NOW()\n);\n",
  "081_precificador_simulations.sql": "CREATE TABLE IF NOT EXISTS precificador_simulations (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  client_id UUID REFERENCES clients(id),\n  title VARCHAR(255),\n  input_data JSONB NOT NULL,\n  result_data JSONB NOT NULL,\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW()\n);\n",
  "082_split_payment_simulations.sql": "CREATE TABLE IF NOT EXISTS split_payment_simulations (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  client_id UUID REFERENCES clients(id),\n  title VARCHAR(255),\n  input_data JSONB NOT NULL,\n  result_data JSONB NOT NULL,\n  created_by UUID,\n  created_at TIMESTAMP DEFAULT NOW()\n);\n",
  "088_property_simulations_v1_kinds.sql": "-- Estende simulation_kind para ITBI, ITCMD e relatório do projeto (pack Pablo v1).\n\nALTER TABLE property_simulations\n  DROP CONSTRAINT IF EXISTS check_property_simulations_simulation_kind;\n\nALTER TABLE property_simulations\n  ADD CONSTRAINT check_property_simulations_simulation_kind\n  CHECK (simulation_kind IN (\n    'locacao_pf_pj',\n    'ganho_capital_imovel',\n    'itbi_integralizacao',\n    'itcmd_doacao',\n    'projeto_pps'\n  ));\n\nCOMMENT ON COLUMN property_simulations.simulation_kind IS\n  'locacao_pf_pj | ganho_capital_imovel | itbi_integralizacao | itcmd_doacao | projeto_pps';\n"
};
